<?php declare(strict_types=1);
namespace Modules\PromptEngine\Services;
use Modules\PromptEngine\DTOs\PromptResultData; use Modules\PromptEngine\Interfaces\{CharacterAnalyzerInterface,DesignPlannerInterface,PromptGeneratorInterface,PromptRepositoryInterface};
final class PromptEngineService { public function __construct(private CharacterValidationService $validator,private CharacterAnalyzerInterface $analyzer,private ExplanationBuilderService $explanations,private DesignPlannerInterface $planner,private PromptGeneratorInterface $prompts,private PromptQualityControlService $quality,private ImageGenerationService $images,private PromptRepositoryInterface $repository){} public function generate(array $data):PromptResultData{$input=$this->validator->validate($data);$analysis=$this->analyzer->analyze($input->character);$plan=$this->planner->plan($analysis,$input);$prompt=$this->prompts->generate($input,$analysis,$plan);$image=$input->mode==='generate_image'?$this->images->generate($input->platform,$prompt->prompt,$input->aspectRatio):null;$result=new PromptResultData($input->toArray(),$analysis->toArray(),$plan->toArray(),$this->explanations->build($analysis->toArray(),$plan->toArray()),$prompt->toArray(),$image);$quality=$this->quality->inspect($result->toArray());$result=new PromptResultData($result->input,$result->analysis,$result->designPlan,$result->explanationVi,$result->imagePrompt,$result->image,$quality);if($input->save&&config('promptengine.config.storage.enabled'))$this->repository->save($result);return $result;} }
